\begin{Theorem}\label{thm:hodge-boundary-problem}
{若 $g\in\mathcal B^k$, 则数据为 $g$ 的 $\mathcal B$ 问题具有唯一解 $v$, 且此解与相同数据的 Hodge Laplace 问题的唯一解相同.}
\end{Theorem}
